//! Static item catalog (names, icons, prime-part recipes) generated by
//! `scripts/gen_catalog.py` from the community warframe-items data.

use serde::Deserialize;
use std::collections::HashMap;

#[derive(Deserialize)]
pub struct Part {
    pub unique: String,
    pub name: String,
    /// How many copies the recipe needs.
    pub need: u32,
}

pub struct Prime {
    pub unique: String,
    #[allow(dead_code)]
    pub name: String,
    pub image: String,
    /// XP at which the item counts as mastered (weapons 450k, frames 900k).
    pub mastery_xp: u64,
    pub parts: Vec<Part>,
}

#[derive(Deserialize)]
struct RawPrime {
    u: String,
    n: String,
    i: String,
    x: u64,
    p: Vec<(String, String, u32)>,
}

#[derive(Deserialize)]
struct Raw {
    items: HashMap<String, (String, String)>,
    primes: Vec<RawPrime>,
}

pub struct Catalog {
    /// unique path -> (display name, image file name)
    pub items: HashMap<String, (String, String)>,
    pub primes: Vec<Prime>,
}

impl Catalog {
    pub fn load() -> Self {
        Self::from_json(include_str!("../assets/catalog.json")).expect("bundled catalog is valid")
    }

    pub fn from_json(s: &str) -> Result<Self, serde_json::Error> {
        let raw: Raw = serde_json::from_str(s)?;
        let primes = raw
            .primes
            .into_iter()
            .map(|p| Prime {
                unique: p.u,
                name: p.n,
                image: p.i,
                mastery_xp: p.x,
                parts: p.p.into_iter().map(|(unique, name, need)| Part { unique, name, need }).collect(),
            })
            .collect();
        Ok(Self { items: raw.items, primes })
    }

    pub fn name(&self, unique: &str) -> Option<&str> {
        self.items.get(unique).map(|(n, _)| n.as_str())
    }

    pub fn image(&self, unique: &str) -> Option<&str> {
        self.items.get(unique).map(|(_, i)| i.as_str()).filter(|i| !i.is_empty())
    }
}
